      const open = r.query.open ? C.visits().find((v) => v.id === r.query.open) : r.query.patient ? vis.find((v) => v.patientId === r.query.patient) : vis[0];
      const list = `<div class="bento min-w-0 self-start p-0"><div class="border-b border-border p-4"><h3 class="font-display text-lg font-semibold">Signed encounters</h3><p class="text-xs text-muted-foreground">documents per visit</p></div><ul class="max-h-[70vh] divide-y divide-border overflow-y-auto">${vis.map((v) => { const d = docs.filter((x) => x.visitId === v.id); return `<li><a href="#/ai/copilot?tab=documents&open=${v.id}" aria-current="${open && open.id === v.id}" class="flex flex-col gap-1 px-4 py-3 hover:bg-muted/60 ${open && open.id === v.id ? "bg-accent-muted/60" : ""}"><span class="flex items-center justify-between gap-2"><span class="truncate text-sm font-medium">${esc(pname(v.patientId))}</span><span class="font-mono text-[10px] text-muted-foreground">${fmtDate(v.at).slice(0, 6)}</span></span><span class="flex flex-wrap gap-1">${d.length ? d.map((x) => badge(DOC_LABEL[x.type].split(" ")[0].toLowerCase(), x.status === "SENT" ? "success" : x.status === "SIGNED" ? "accent" : "warning")).join("") : badge("note only", "default")}</span></a></li>`; }).join("")}</ul></div>`;
      body = `<div class="grid grid-cols-1 gap-4 lg:grid-cols-[20rem_1fr]">${list}<div class="min-w-0">${open ? documentsPanel(open) : emptyState("Pick an encounter")}</div></div>`;
